function fids = undoReceiverPhaseCycle(fids)
% Undo the phase cycling of the receiver by removing the zero-order phase
% of the first point of every FID (i.e. of every average of every
% sub-spectrum). This is the operation that is also applied to Philips data
% that is read through the NIfTI-MRS loader (io_loadspec_niimrs).
% All-zero FIDs (e.g. the empty rows of Philips reference scans) are left
% untouched instead of being turned into NaNs.

firstPoints  = fids(1,:,:,:,:,:);
magnitudes   = abs(firstPoints);
phaseFactors = conj(firstPoints);
nonZero      = magnitudes > 0;
phaseFactors(nonZero)  = phaseFactors(nonZero)./magnitudes(nonZero);
phaseFactors(~nonZero) = 1;
fids = fids .* repmat(phaseFactors,[size(fids,1) 1]);

end


