%% Functions for processing
function specs = collapseToSubSpecs(specs,dims)
% Collapse a spectrum array so that only the frequency dimension and the
% sub-spectra dimension are left, i.e. one trace per acquisition condition.
% This is used to judge the polarity of a reference peak on the average of
% all transients (and not on single, noisy transients), while keeping the
% sub-spectra of edited data separate, so that each of them can receive its
% own polarity factor.

freqDim = 1;
if isfield(dims,'t') && dims.t > 0
    freqDim = dims.t;
end
subSpecDim = 0;
if isfield(dims,'subSpecs') && dims.subSpecs > 0
    subSpecDim = dims.subSpecs;
end

for dd = 1 : ndims(specs)
    if dd ~= freqDim && dd ~= subSpecDim && size(specs,dd) > 1
        specs = mean(specs,dd);
    end
end

end

